   "exp": "الشرح: ← صح. النص كيقول أن الأبناك وصناديق التوفير كيقدموها للشباب (\"bieten Banken und alle Sparkassen Jugendlichen... an\"). هادو كيتعتبرو مؤسسات مالية عديدة.",
