   "ar": "الحنين الألماني للمكتب الفردي: مكتبي، بيسيي، البيرو ديالي. الغرفة الفردية كانت جزء أساسي من ثقافة العمل الألمانية. وحتى اليوم باقيين بزاف عندهم، واللي ما عندوش كيحلم بيه على الأقل. هاد الرغبة ألمانية بامتياز. كيقول روبرت مينكه من شركة الاستشارات العقارية كوشمان آند ويكفيلد: «مقارنة بالموظفين فبلدان أخرى، حنا جالسين مرتاحين بزاف. واخا كاع الموظفين عندهم نفس الأثاث، كل واحد جالس فمكتبو الخاص، كيستعمل خزاين الملفات ديالو وكيبغي يسد الباب على راسو». الشركة نشرات دراسة كتبين أن الموظفين الألمان عالمياً عندهم أكبر مساحة: فالمتوسط 30 متر مربع للشخص."
