   "c": "a",
   "exp": "الجواب A كيبقى صحيح، حيت تعلم اللغة ممكن ينجح إلا كان بواحد \"المنهجية\" أو \"النظام\" لي مفهوم للطفل (بحال المثال ديال الدار/الزنقة).",
